func TestGetURL(t *testing.T) {
	var tests = []struct {
		name     string
		lat      float32
		long     float32
		key      string
		contains []string
	}{
		{"successfully accept negative coordinates", 10.01, 34.560001, "ANYTHING", []string{"q=10.010000,34.560001"}},
		{"successfully accept positive coordinates", -10.01, -34.560001, "ANYTHING", []string{"q=-10.010000,-34.560001"}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := os.Setenv(apiKeyEnvVar, tt.key)
			if err != nil {
				t.Fatalf("unexpected error setting up test: %v", err)
			}
			output := getURL(tt.lat, tt.long)
			if !strings.Contains(output, baseURL) {
				t.Errorf("expected %s in the URL: %s", baseURL, output)
			}
			for _, s := range tt.contains {
				if !strings.Contains(output, s) {
					t.Errorf("expected %s in the URL: %s", s, output)
				}
			}
		})
	}
}

func TestGetUrl_Panic(t *testing.T) {
	defer func() { _ = recover() }()
	err := os.Setenv(apiKeyEnvVar, "")
	if err != nil {
		t.Fatalf("unexpected error setting up test: %v", err)
	}

	_ = getURL(0.0, 0.0)

	t.Errorf("expected panic, but did not")
}

func TestConvert(t *testing.T) {
	var tests = []struct {
		name  string
		input apiResponse
		want  map[string]forecast.WeatherOutput
	}{
		{"Empty should convert to empty", apiResponse{}, map[string]forecast.WeatherOutput{}},
		{name: "Populated response should convert to populated forecast", input: apiResponse{
			Forecast: days{
				ForecastDay: []forecastDay{
					{Date: "one", Day: day{
						MaxTempC:      1.2,
						MinTempC:      1.2,
						MaxWindKPH:    1.1,
						TotalPrecipMM: 2.2,
						AvgVisKM:      10.10,
						AvgHumidity:   40,
						ChanceOfRain:  10,
						UV:            2.2,
					}},
					{Date: "two", Day: day{
						MaxTempC:      3.4,
						MinTempC:      3.4,
						MaxWindKPH:    5.5,
						TotalPrecipMM: 3.3,
						AvgVisKM:      20.20,
						AvgHumidity:   50,
						ChanceOfRain:  20,
						UV:            3.3,
					}},
				}}}, want: map[string]forecast.WeatherOutput{
			"day1": forecast.WeatherOutput{
				Date:          "one",
				MaxTempC:      1.2,
				MinTempC:      1.2,
				MaxWindKPH:    1.1,
				TotalPrecipMM: 2.2,
				AvgVisKM:      10.10,
				AvgHumidity:   40,
				ChanceOfRain:  10,
				UV:            2.2,
			},
			"day2": forecast.WeatherOutput{
				Date:          "two",
				MaxTempC:      3.4,
				MinTempC:      3.4,
				MaxWindKPH:    5.5,
				TotalPrecipMM: 3.3,
				AvgVisKM:      20.20,
				AvgHumidity:   50,
				ChanceOfRain:  20,
				UV:            3.3,
			},
		}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			output := convert(&tt.input)
			if !maps.Equal(output, tt.want) {
				t.Errorf("Expected %v, got %v", tt.want, output)
			}
		})
	}
}
